def amp_db(size,rho,lf):
    return DBUR[(size,rho_tab(rho),lf)]*AMBF[size]

# ---------------- pulling ----------------
def cable_cfg(size, conduit):
    cm,d,w = CABLE[size]; D = CONDUIT[conduit][1]
    ratio = D/d; x = d/(D-d)
    if ratio < 2.8: cfg='tri'; wc = 1/math.sqrt(1-x*x)
    else: cfg='cradled'; wc = 1+(4/3)*x*x
    return cfg, wc, ratio, 3*d*d/(D*D)*100
